from pathlib import Path
import json,re
root=Path(__file__).resolve().parents[1]
shell=(root/'index.html').read_text()
shell=re.sub(r'<script defer src="[^"]+"></script>','',shell)
shell=shell.replace('<link rel="stylesheet" href="assets/fonts.css">','').replace('<link rel="stylesheet" href="assets/styles.css">','<!--EXERCISE_STYLE-->')
shell=shell.replace('</body>','<!--EXERCISE_RUNTIME--></body>')
shell=shell.replace('Negligence | Studies De Jure Exercises','Decision tree exercise').replace('Explore negligence through questions, explanations, and a clickable decision tree.','An interactive decision-tree exercise.').replace('Outlined: question · Green: recovery · Amber: claim fails or recovery barred','Outlined: question · Green: positive outcome · Amber: negative outcome')
payload={'shell':shell,'css':(root/'assets/fonts.css').read_text()+'\n'+(root/'assets/styles.css').read_text(),'js':'\n'.join((root/'assets'/name).read_text() for name in ['model.js','markdown.js','app.js'])}
(root/'assets/export-template.js').write_text('/* Generated by scripts/build-export-template.py */\nwindow.STUDENT_TEMPLATE = '+json.dumps(payload,ensure_ascii=True)+';\n')
